parameters.new_string:
#!/usr/bin/env python3
from neo4j import GraphDatabase
import sys

def find_house_with_most_kings():
    # Try multiple connection possibilities
    connection_configs = [
        ("bolt://localhost:7687", "neo4j", "password"),
        ("bolt://localhost:7687", "neo4j", "neo4j"),
        ("bolt://localhost:7687", "", ""),
        ("neo4j://localhost:7687", "neo4j", "password"),
        ("neo4j://localhost:7687", "neo4j", "neo4j"),
    ]

    driver = None
    for uri, username, password in connection_configs:
        try:
            if username and password:
                driver = GraphDatabase.driver(uri, auth=(username, password))
            else:
                driver = GraphDatabase.driver(uri)
            # Test the connection
            with driver.session() as test_session:
                test_session.run("RETURN 1")
            print(f"Connected successfully with {uri}")
            break
        except Exception as e:
            if driver:
                driver.close()
            driver = None
            continue

    if not driver:
        print("Could not establish connection to Neo4j")
        return

