cat > /tmp/find_kings_houses.py << 'EOF'
import subprocess
import json

query = """
MATCH (h:House)<-[:BELONGS_TO]-(k:King)
RETURN h.name AS house, COUNT(k) AS king_count
ORDER BY king_count DESC
"""

result = subprocess.run(
    ["cypher-shell", "-a", "neo4j://localhost:7687", "-u", "neo4j", "-p", "password", query],
    capture_output=True,
    text=True
)

if result.returncode == 0:
    lines = result.stdout.strip().split('\n')
    if len(lines) > 1:
        # Skip header
        max_count = None
        top_houses = []

        for line in lines[1:]:
            if line.strip():
                parts = line.split('|')
                if len(parts) >= 2:
                    house = parts[0].strip()
                    try:
                        count = int(parts[1].strip())
                        if max_count is None:
                            max_count = count

                        if count == max_count:
                            top_houses.append(house)
                    except:
                        pass

        for house in sorted(top_houses):
            print(house)
else:
    print("Error:", result.stderr)
EOF
